(function(root){'use strict';
const KEYS={tabs:'albion-workspace-v1',favorites:'albion-favorites-v1',tree:'albion-navigation-v1'},servers=['europe','west','east'];
const clone=x=>JSON.parse(JSON.stringify(x)),object=x=>x&&typeof x==='object'&&!Array.isArray(x);
function safe(x,depth=0){if(depth>35)throw Error('Слишком сложный черновик.');if(object(x)||Array.isArray(x))for(const [k,v]of Object.entries(x)){if(['__proto__','prototype','constructor'].includes(k))throw Error('Повреждены настройки.');safe(v,depth+1);}if(typeof x==='number'&&!Number.isFinite(x))throw Error('Некорректное число.');}
function target(t){if(!object(t)||!['section','item','saved'].includes(t.type)||typeof t.id!=='string'||!t.id||t.id.length>160)throw Error('Некорректное назначение.');if(t.mode!==undefined&&typeof t.mode!=='string')throw Error('Некорректный раздел.');safe(t);return clone(t);}
const targetKey=t=>JSON.stringify([t.type,t.id,t.mode||'',t.filter||'',t.anchor||'']);
const identity=t=>targetKey(t.target)+'|'+t.server+'|'+t.characterId;
function tab(t){if(!object(t)||typeof t.id!=='string'||!t.id||!servers.includes(t.server)||typeof t.characterId!=='string'||typeof t.name!=='string'||t.name.length>60||typeof t.pinned!=='boolean'||!object(t.draft))throw Error('Рабочая вкладка повреждена.');target(t.target);safe(t);return clone(t);}
function readTabs(storage){const raw=storage.getItem(KEYS.tabs);if(!raw)return null;const d=JSON.parse(raw);if(d.version!==1||!Array.isArray(d.tabs)||d.tabs.length>20||!Array.isArray(d.closed)||d.closed.length>20)throw Error('Не удалось прочитать рабочие вкладки. Исходные данные сохранены.');d.tabs=d.tabs.map(tab);d.closed=d.closed.map(tab);const ids=new Set(d.tabs.map(t=>t.id)),closedIds=new Set(d.closed.map(t=>t.id));if(closedIds.size!==d.closed.length||d.closed.some(t=>ids.has(t.id)))throw Error('Список закрытых вкладок повреждён.');if(ids.size!==d.tabs.length||d.active!==null&&!ids.has(d.active))throw Error('Активная вкладка повреждена.');return d;}
function empty(){return {version:1,tabs:[],closed:[],active:null};}
function open(d,t,duplicate=false){t=tab(t);const existing=!duplicate&&d.tabs.find(x=>identity(x)===identity(t));if(existing)return {...d,active:existing.id};if(d.tabs.length>=20)throw Error('Открыто 20 вкладок. Закройте ненужную перед открытием новой.');return {...d,tabs:[...d.tabs,t].sort((a,b)=>Number(b.pinned)-Number(a.pinned)),active:t.id};}
function close(d,id){const t=d.tabs.find(x=>x.id===id);if(!t)return d;const index=d.tabs.indexOf(t),tabs=d.tabs.filter(x=>x.id!==id);return {...d,tabs,closed:[...d.closed.filter(x=>x.id!==id),clone(t)].slice(-20),active:d.active===id?(tabs[Math.min(index,tabs.length-1)]?.id||null):d.active};}
function reopen(d){if(!d.closed.length)return d;if(d.tabs.length>=20)throw Error('Открыто 20 вкладок. Закройте ненужную.');const t=d.closed.at(-1);return open({...d,closed:d.closed.slice(0,-1)},t,true);}
function closeGroup(d,id,kind){const index=d.tabs.findIndex(t=>t.id===id);for(const t of [...d.tabs])if(!t.pinned&&t.id!==id&&(kind==='others'||kind==='right'&&d.tabs.indexOf(t)>index))d=close(d,t.id);return d;}
function readFavorites(storage){const raw=storage.getItem(KEYS.favorites);if(!raw)return {version:1,items:[]};const d=JSON.parse(raw);if(d.version!==1||!Array.isArray(d.items)||d.items.length>50)throw Error('Не удалось прочитать избранное. Исходные данные сохранены.');const seen=new Set(),ids=new Set(),items=[];for(const x of d.items){if(!object(x)||typeof x.id!=='string'||ids.has(x.id)||typeof x.name!=='string'||x.name.length>40||typeof x.customName!=='boolean')throw Error('Избранное повреждено.');target(x.target);safe(x);if(x.context&&(!servers.includes(x.context.server)||typeof x.context.characterId!=='string'))throw Error('Контекст избранного повреждён.');ids.add(x.id);const k=targetKey(x.target)+'|'+JSON.stringify(x.context||null);if(!seen.has(k)){seen.add(k);items.push(clone(x));}}return {version:1,items};}
function favorite(d,x){target(x.target);const key=targetKey(x.target)+'|'+JSON.stringify(x.context||null);if(d.items.some(v=>targetKey(v.target)+'|'+JSON.stringify(v.context||null)===key))return d;if(d.items.length>=50)throw Error('В избранном 50 ссылок. Уберите ненужную перед добавлением.');return {version:1,items:[...d.items,clone(x)]};}
function move(d,id,offset){const items=[...d.items],i=items.findIndex(x=>x.id===id),j=Math.max(0,Math.min(items.length-1,i+offset));if(i<0)return d;const [x]=items.splice(i,1);items.splice(j,0,x);return {...d,items};}
function readTree(storage){const raw=storage.getItem(KEYS.tree);if(!raw)return {version:1,width:250,expanded:['production','resources','items','island-group','trade'],hidden:storage.getItem('albion-sidebar-collapsed')==='true',scroll:0};const d=JSON.parse(raw);if(d.version!==1||!Array.isArray(d.expanded)||d.expanded.some(x=>typeof x!=='string')||!Number.isFinite(d.width)||typeof d.hidden!=='boolean'||!Number.isFinite(d.scroll))throw Error('Не удалось прочитать настройки дерева.');return {...d,width:Math.max(220,Math.min(360,d.width)),scroll:Math.max(0,d.scroll)};}
const api={KEYS,clone,target,targetKey,identity,tab,empty,readTabs,open,close,reopen,closeGroup,readFavorites,favorite,move,readTree};root.WorkspaceMath=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
